-- Synthetic Seed Data Export (All 9 Tables in FK Order)
-- Seed: 20261022, Scale: 1.0
BEGIN;

CREATE TABLE IF NOT EXISTS audit_events (
	id SERIAL NOT NULL, 
	event_id VARCHAR(32) NOT NULL, 
	event_type VARCHAR(64) NOT NULL, 
	actor_id VARCHAR(64), 
	target_entity_type VARCHAR(64) NOT NULL, 
	target_entity_id VARCHAR(64) NOT NULL, 
	occurred_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	details JSON NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_audit_events PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS courses (
	id SERIAL NOT NULL, 
	public_id VARCHAR(32) NOT NULL, 
	title VARCHAR(255) NOT NULL, 
	version VARCHAR(32) NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_courses PRIMARY KEY (id), 
	CONSTRAINT "ck_courses_`chk_course_status`" CHECK (status IN ('ACTIVE', 'ARCHIVED'))
);

CREATE TABLE IF NOT EXISTS issuers (
	id SERIAL NOT NULL, 
	public_id VARCHAR(32) NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	public_key_pem TEXT NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_issuers PRIMARY KEY (id), 
	CONSTRAINT "ck_issuers_`chk_issuer_status`" CHECK (status IN ('ACTIVE', 'SUSPENDED', 'RETIRED'))
);

CREATE TABLE IF NOT EXISTS learners (
	id SERIAL NOT NULL, 
	public_id VARCHAR(32) NOT NULL, 
	full_name VARCHAR(255) NOT NULL, 
	email VARCHAR(255) NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_learners PRIMARY KEY (id), 
	CONSTRAINT "ck_learners_`chk_learner_status`" CHECK (status IN ('ACTIVE', 'SUSPENDED'))
);

CREATE TABLE IF NOT EXISTS credential_rules (
	id SERIAL NOT NULL, 
	course_id INTEGER NOT NULL, 
	rule_version VARCHAR(32) NOT NULL, 
	min_score NUMERIC(5, 2) NOT NULL, 
	required_completion_status VARCHAR(32) NOT NULL, 
	effective_from TIMESTAMP WITH TIME ZONE NOT NULL, 
	effective_to TIMESTAMP WITH TIME ZONE NOT NULL, 
	active BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_credential_rules PRIMARY KEY (id), 
	CONSTRAINT "ck_credential_rules_`chk_rule_dates`" CHECK (effective_to > effective_from), 
	CONSTRAINT "ck_credential_rules_`chk_min_score`" CHECK (min_score >= 0.00 AND min_score <= 100.00), 
	CONSTRAINT fk_credential_rules_course_id_courses FOREIGN KEY(course_id) REFERENCES courses (id) ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS completion_records (
	id SERIAL NOT NULL, 
	public_id VARCHAR(64) NOT NULL, 
	learner_id INTEGER NOT NULL, 
	course_id INTEGER NOT NULL, 
	rule_id INTEGER NOT NULL, 
	assessment_score NUMERIC(5, 2) NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	completion_timestamp TIMESTAMP WITH TIME ZONE NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_completion_records PRIMARY KEY (id), 
	CONSTRAINT "ck_completion_records_`chk_assessment_score`" CHECK (assessment_score >= 0.00 AND assessment_score <= 100.00), 
	CONSTRAINT "ck_completion_records_`chk_completion_status`" CHECK (status IN ('COMPLETED', 'IN_PROGRESS', 'FAILED')), 
	CONSTRAINT fk_completion_records_learner_id_learners FOREIGN KEY(learner_id) REFERENCES learners (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_completion_records_course_id_courses FOREIGN KEY(course_id) REFERENCES courses (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_completion_records_rule_id_credential_rules FOREIGN KEY(rule_id) REFERENCES credential_rules (id) ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS credentials (
	id SERIAL NOT NULL, 
	public_id VARCHAR(64) NOT NULL, 
	completion_id INTEGER NOT NULL, 
	issuer_id INTEGER NOT NULL, 
	issued_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	canonical_payload_hash VARCHAR(64) NOT NULL, 
	issuer_signature TEXT NOT NULL, 
	payload_snapshot JSON NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_credentials PRIMARY KEY (id), 
	CONSTRAINT "ck_credentials_`chk_cred_status`" CHECK (status IN ('ACTIVE', 'REVOKED')), 
	CONSTRAINT fk_credentials_completion_id_completion_records FOREIGN KEY(completion_id) REFERENCES completion_records (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_credentials_issuer_id_issuers FOREIGN KEY(issuer_id) REFERENCES issuers (id) ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS revocations (
	id SERIAL NOT NULL, 
	public_id VARCHAR(64) NOT NULL, 
	credential_id INTEGER NOT NULL, 
	revoked_by_actor_id VARCHAR(64) NOT NULL, 
	reason_code VARCHAR(64) NOT NULL, 
	revocation_timestamp TIMESTAMP WITH TIME ZONE NOT NULL, 
	notes TEXT, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_revocations PRIMARY KEY (id), 
	CONSTRAINT "ck_revocations_`chk_revocation_reason`" CHECK (reason_code IN ('ACADEMIC_MISCONDUCT', 'ADMINISTRATIVE_ERROR', 'RESCINDED', 'OTHER')), 
	CONSTRAINT fk_revocations_credential_id_credentials FOREIGN KEY(credential_id) REFERENCES credentials (id) ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS verification_requests (
	id SERIAL NOT NULL, 
	public_id VARCHAR(32) NOT NULL, 
	credential_id INTEGER, 
	requested_identifier VARCHAR(128) NOT NULL, 
	verification_timestamp TIMESTAMP WITH TIME ZONE NOT NULL, 
	outcome VARCHAR(32) NOT NULL, 
	reason_code VARCHAR(64) NOT NULL, 
	integrity_check_passed BOOLEAN NOT NULL, 
	issuer_authenticated BOOLEAN NOT NULL, 
	requester_ip VARCHAR(64), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	CONSTRAINT pk_verification_requests PRIMARY KEY (id), 
	CONSTRAINT "ck_verification_requests_`chk_verif_outcome`" CHECK (outcome IN ('VALID', 'REVOKED', 'TAMPERED', 'NOT_FOUND', 'INVALID_ISSUANCE')), 
	CONSTRAINT fk_verification_requests_credential_id_credentials FOREIGN KEY(credential_id) REFERENCES credentials (id) ON DELETE SET NULL
);

